    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    g = [row[:] for row in grid]
    # Find the horizontal seed run (excluding the background and destination markers).
    candidates = []
    for r, row in enumerate(grid):
        xs = [c for c, v in enumerate(row) if v != bg and v != 6]
        if len(xs) >= 3:
            candidates.append((len(xs), r, xs))
    if not candidates:
        return g
    _, sr, xs = max(candidates)
    vals = [grid[sr][c] for c in xs]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 6:
                start = c - len(vals)//2
                for j, color in enumerate(vals):
                    x = start+j
                    if 0 <= x < w:
                        g[r][x] = color
    return g

